import json, re, random, sys, chess

RULES = [(re.compile(p), r) for p, r in json.load(open("/tmp/obench-cell-px5ezx2g/bench_opencode_regex-chess_fw4w1sfp/re.json"))]


def run(fen):
    for p, r in RULES:
        fen = p.sub(r, fen)
    return fen.split("\n")


def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    board = chess.Board(fen)
    exp = set()
    for m in board.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        b = board.copy(); b.push(m)
        exp.add(" ".join(b.fen().split(" ")[:-2]))
    ok = len(ours) == len(exp) and all(x in exp or x.rpartition(" ")[0] + " -" in exp for x in ours)
    if not ok:
        print("FAIL", fen)
        print(" extra:", [x for x in ours if not (x in exp or x.rpartition(" ")[0] + " -" in exp)])
        norm = set()
        for x in ours:
            norm.add(x); norm.add(x.rpartition(" ")[0] + " -")
        print(" missing:", [x for x in exp if x not in norm])
    return ok


ex = "rnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P5/q4Kb1 w kq - 0 1"
print("\n".join(run(ex)))
check(ex)
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = fails = 0
for g in range(300):
    b = chess.Board()
    for ply in range(200):
        if b.is_game_over():
            break
        if b.turn == chess.WHITE:
            n += 1
            if not check(b.fen()):
                fails += 1
                if fails > 5:
                    sys.exit(1)
        moves = list(b.legal_moves)
        # bias toward captures/checks/castling for coverage
        pref = [m for m in moves if b.is_castling(m) or b.is_en_passant(m) or m.promotion]
        b.push(random.choice(pref) if pref and random.random() < 0.7 else random.choice(moves))
print("tested", n, "fails", fails)
